// Canvas and the percent-based source highlight always scale as one surface.
function createSourceViewer(host,{allowExpand=true}={}){
 const controller=new AbortController(),signal=controller.signal;
 const panel=document.createElement('div');panel.className='source-zoom-panel';
 const toolbar=document.createElement('div');toolbar.className='source-zoom-toolbar';toolbar.setAttribute('aria-label','Bildzoom');
 const viewport=document.createElement('div');viewport.className='source-zoom-viewport';viewport.tabIndex=0;viewport.setAttribute('aria-label','Original ansehen und vergrößern');viewport.dir='ltr';
 const stage=document.createElement('div');stage.className='source-zoom-stage';viewport.append(stage);
 let canvas=null,box=null,scale=1,fit=1,atFit=true,destroyed=false,pinchDistance=0,resizeFrame=0,textItems=null,getText=null,textLayerOn=false,textContent='';
 const pointers=new Map(),buttonLabels=[];
 const button=(text,label,action)=>{const el=document.createElement('button');el.type='button';el.className='text-button';el.textContent=text;el.setAttribute('aria-label',label);el.addEventListener('click',action,{signal});toolbar.append(el);buttonLabels.push({el,text,label});return el;};
 const minus=button('−','Verkleinern',()=>zoom(scale/1.3));
 const amount=document.createElement('output');amount.className='source-zoom-amount';amount.setAttribute('aria-label','Zoomstufe');toolbar.append(amount);
 const plus=button('+','Vergrößern',()=>zoom(scale*1.3));
 button('Einpassen','Bild einpassen',()=>reset());
 const textButton=button('Text auswählen','Text auf dem Original auswählen',()=>void toggleText());
 const copyButton=button('Text kopieren','Erkannten Text kopieren',()=>void copyText());copyButton.hidden=true;
 const region=button('Markierung','Markierung vergrößern',()=>focusRegion());region.disabled=true;
 if(allowExpand)button('↗','Großansicht öffnen',event=>expand(event.currentTarget));
 const help=document.createElement('p');help.className='source-zoom-help';help.textContent='Mausrad zum Zoomen · Ziehen zum Verschieben';
 panel.append(toolbar,viewport,help);host.replaceChildren(panel);
 function localize(){const t=value=>window.TOCRI18n?.t(value)||value;for(const {el,text,label}of buttonLabels){el.textContent=t(text);el.setAttribute('aria-label',t(label));}toolbar.setAttribute('aria-label',t('Bildzoom'));viewport.setAttribute('aria-label',t('Original ansehen und vergrößern'));amount.setAttribute('aria-label',t('Zoomstufe'));help.textContent=t('Mausrad zum Zoomen · Ziehen zum Verschieben');stage.querySelector('.source-highlight')?.setAttribute('aria-label',t('Markierte Originalstelle'));if(canvas?.dataset.sourcePage)canvas.setAttribute('aria-label',t('Originalseite {page}: {file}').replaceAll('{page}',canvas.dataset.sourcePage).replaceAll('{file}',canvas.dataset.sourceName));}
 window.addEventListener('translateocr-locale',localize,{signal});localize();
 function bounds(){return viewport.getBoundingClientRect();}
 function paint(){if(!canvas)return;stage.style.width=`${Math.round(canvas.width*scale)}px`;stage.style.height=`${Math.round(canvas.height*scale)}px`;amount.textContent=`${Math.round(scale*100)}%`;minus.disabled=scale<=fit+.001;plus.disabled=scale>=8;for(const node of stage.querySelectorAll('.source-selectable-text')){const item=node._sourceText;node.style.left=`${item.x/canvas.width*100}%`;node.style.top=`${item.y/canvas.height*100}%`;node.style.width=`${Math.max(item.w,2)/canvas.width*100}%`;node.style.height=`${Math.max(item.h,8)/canvas.height*100}%`;node.style.fontSize=`${Math.max(7,item.h*scale*.8)}px`;}}
 function zoom(next,x=viewport.clientWidth/2,y=viewport.clientHeight/2){if(!canvas)return;next=Math.max(fit,Math.min(8,next));const oldOffset=Math.max(0,(viewport.clientWidth-canvas.width*scale)/2),newOffset=Math.max(0,(viewport.clientWidth-canvas.width*next)/2);const anchor=sourceZoomAnchor(scale,next,viewport.scrollLeft,viewport.scrollTop,x,y,oldOffset,newOffset);scale=next;atFit=Math.abs(scale-fit)<.001;paint();viewport.scrollLeft=anchor.left;viewport.scrollTop=anchor.top;}
 function reset(){if(!canvas)return;fit=Math.min(1,Math.max(.02,Math.min((viewport.clientWidth-2)/canvas.width,(viewport.clientHeight-2)/canvas.height)));scale=fit;atFit=true;paint();viewport.scrollLeft=0;viewport.scrollTop=0;}
 function focusRegion(){if(!canvas||!box)return;zoom(sourceRegionScale(canvas.width,canvas.height,viewport.clientWidth,viewport.clientHeight,box,fit));viewport.scrollLeft=(box[0]+box[2]/2)*canvas.width*scale-viewport.clientWidth/2;viewport.scrollTop=(box[1]+box[3]/2)*canvas.height*scale-viewport.clientHeight/2;viewport.focus({preventScroll:true});}
 function renderText(items){stage.querySelector('.source-text-select-layer')?.remove();const layer=document.createElement('div');layer.className='source-text-select-layer';layer.setAttribute('aria-label','Erkannter Text auf dem Original');for(const item of items){if(!item.text?.trim())continue;const span=document.createElement('span');span.className='source-selectable-text';span.textContent=item.text;span.dir=/[\u0600-\u06ff]/u.test(item.text)?'rtl':'auto';span._sourceText=item;layer.append(span);}stage.append(layer);textLayerOn=true;textButton.textContent=window.TOCRI18n?.t('Textauswahl ausblenden')||'Textauswahl ausblenden';copyButton.hidden=!textContent;paint();}
 async function toggleText(){if(textLayerOn){stage.querySelector('.source-text-select-layer')?.remove();textLayerOn=false;textButton.textContent=window.TOCRI18n?.t('Text auswählen')||'Text auswählen';copyButton.hidden=true;return;}textButton.disabled=true;textButton.textContent=window.TOCRI18n?.t('Text wird erkannt …')||'Text wird erkannt …';try{let result;if(textItems?.length)result={words:textItems,text:textItems.map(i=>i.text).join(' ')};else if(getText)result=await getText();else{const {localOcr}=await import('/source-text.js');result=await localOcr(canvas);}textItems=result.words||[];textContent=result.text||textItems.map(i=>i.text).join(' ');renderText(textItems);if(!textItems.length)throw new Error('Kein Text erkannt.');}catch(error){toast(error.message||'Text konnte nicht erkannt werden.');textButton.textContent=window.TOCRI18n?.t('Text auswählen')||'Text auswählen';}finally{textButton.disabled=false;}}
 async function copyText(){if(!textContent)return;try{await navigator.clipboard.writeText(textContent);}catch{const area=document.createElement('textarea');area.value=textContent;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove();}toast(window.TOCRI18n?.t('Erkannter Text kopiert.')||'Erkannter Text kopiert.');}
 function setCanvas(next,location=null,options={}){canvas=next;box=location;textItems=options.textItems||null;getText=options.getText||null;textLayerOn=false;textContent='';canvas.classList.add('source-zoom-canvas');canvas.style.width='100%';canvas.style.height='100%';stage.replaceChildren(canvas);region.disabled=!box;textButton.hidden=false;copyButton.hidden=true;if(box){const marker=document.createElement('div');marker.className='source-highlight';marker.dataset.noTranslate='';marker.setAttribute('role','img');marker.setAttribute('aria-label','Markierte Originalstelle');marker.style.cssText=`left:${box[0]*100}%;top:${box[1]*100}%;width:${box[2]*100}%;height:${box[3]*100}%`;stage.append(marker);}localize();reset();}
 function expand(launcher){if(!canvas)return;const t=value=>window.TOCRI18n?.t(value)||value;const dialog=document.createElement('dialog');dialog.className='workspace-dialog source-lightbox';dialog.setAttribute('aria-label',t('Großansicht öffnen'));const header=document.createElement('div');header.className='workspace-dialog-header';const title=document.createElement('h2');title.textContent=t('Original');const close=document.createElement('button');close.type='button';close.className='text-button';close.textContent=t('Zurück zum Dokument');header.append(title,close);const body=document.createElement('div');body.className='workspace-dialog-body';dialog.append(header,body);document.body.append(dialog);window.TOCRDialogs.bind(dialog);window.TOCRDialogs.open(dialog,launcher);const viewer=createSourceViewer(body,{allowExpand:false});const copy=document.createElement('canvas');copy.dataset.noTranslate='';copy.width=canvas.width;copy.height=canvas.height;copy.getContext('2d').drawImage(canvas,0,0);copy.setAttribute('aria-label',canvas.getAttribute('aria-label')||'Original');if(canvas.dataset.sourcePage){copy.dataset.sourcePage=canvas.dataset.sourcePage;copy.dataset.sourceName=canvas.dataset.sourceName;}viewer.setCanvas(copy,box,{textItems,getText});close.onclick=()=>window.TOCRDialogs.close(dialog);dialog.addEventListener('close',()=>{viewer.destroy();dialog.remove();},{once:true});}
 viewport.addEventListener('wheel',event=>{if(!canvas)return;event.preventDefault();const r=bounds();zoom(scale*Math.exp(-Math.max(-180,Math.min(180,event.deltaY))*.004),event.clientX-r.left,event.clientY-r.top);},{passive:false,signal});
 viewport.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('.source-selectable-text'))return;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});viewport.setPointerCapture(event.pointerId);viewport.classList.add('is-dragging');pinchDistance=0;},{signal});
 viewport.addEventListener('pointermove',event=>{const previous=pointers.get(event.pointerId);if(!previous)return;const dx=event.clientX-previous.x,dy=event.clientY-previous.y;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y),r=bounds();if(pinchDistance)zoom(scale*distance/pinchDistance,(a.x+b.x)/2-r.left,(a.y+b.y)/2-r.top);pinchDistance=distance;}else{viewport.scrollLeft-=dx;viewport.scrollTop-=dy;}},{signal});
 const release=event=>{pointers.delete(event.pointerId);pinchDistance=0;if(!pointers.size)viewport.classList.remove('is-dragging');};viewport.addEventListener('pointerup',release,{signal});viewport.addEventListener('pointercancel',release,{signal});
 viewport.addEventListener('dblclick',event=>{event.preventDefault();if(box)focusRegion();else if(atFit)zoom(Math.max(1,fit*2));else reset();},{signal});
 viewport.addEventListener('keydown',event=>{if(['+','=','-','0','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();if(event.key==='+'||event.key==='=')zoom(scale*1.3);else if(event.key==='-')zoom(scale/1.3);else if(event.key==='0')reset();else if(event.key==='ArrowLeft')viewport.scrollLeft-=48;else if(event.key==='ArrowRight')viewport.scrollLeft+=48;else if(event.key==='ArrowUp')viewport.scrollTop-=48;else viewport.scrollTop+=48;}},{signal});
 const observer=new ResizeObserver(()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{if(destroyed||!canvas)return;const wasFit=atFit;fit=Math.min(1,Math.max(.02,Math.min((viewport.clientWidth-2)/canvas.width,(viewport.clientHeight-2)/canvas.height)));if(wasFit)reset();else if(scale<fit)zoom(fit);});});observer.observe(viewport);
 return {setCanvas,focusRegion,reset,zoom,destroy(){destroyed=true;controller.abort();observer.disconnect();cancelAnimationFrame(resizeFrame);pointers.clear();}};
}
